    },

    recordLoopEscapeVisit: function(a) {
      if (typeof a.getNote !== 'function') return;
      var now = performance.now();
      if (a.vars.lastEscapeNoteAt && (now - a.vars.lastEscapeNoteAt < 15000)) return;

      var existingNoteObj = findExistingNoteInRadius(a, 'escape de bucle', 3);
      if (existingNoteObj) return;

      var surfY = a.surfaceY(a.x, a.z);
      if (surfY < 0) return;

      var escapeVisits = {};
      escapeVisits[a.name] = 1;
      // OJO: esta nota NO la dispara detectar un bucle, sino agotarse la cuenta atras v.escapeSteps, que
      // arman 9 maniobras distintas (borde, frecuencia, ciclo, desatasco, desmonte de pino). Antes todas
      // escribian el mismo texto fijo de "oscilacion en micro-zona" y eso despistaba al leer las trazas:
      // una serpiente en linea recta sembraba una nota de bucle 5 ticks despues de una redireccion de
      // borde. Ahora cada maniobra deja su motivo en v.escapeMotivo y aqui se declara tal cual.
      var motivo = a.vars.escapeMotivo;
      var causeStr = motivo
        ? ('Causa: Fin de maniobra de escape (' + motivo + ').')
        : 'Causa: Fin de maniobra de escape (motivo no registrado).';
      var outLines = ['escape de bucle', a.name + ': 1 veces', causeStr, get3x3HeightGridStr(a, a.x, a.z, surfY)];
      var notePos = [a.x, surfY, a.z];
      a.note(outLines.join('\n'), notePos);
      a.vars.lastEscapeNoteAt = now;
      attachNoteTrace(a, notePos, 'escape de bucle', causeStr,
        'onTick() -> [' + (motivo || 'motivo no registrado') + '] -> recordLoopEscapeVisit() -> a.note()');
    },

    isTrapPit: function(a, nx, nz) {
      var W = mc.dim.x, D = mc.dim.z;
      if (nx < 1 || nx >= W - 1 || nz < 1 || nz >= D - 1) return true;
      var ny = a.surfaceY(nx, nz);
      if (ny < 0) return true;

      var noteObj = findExistingNoteInRadius(a, 'foso trampa', 2);
      if (noteObj && noteObj.note && noteObj.note.indexOf(a.name + ':') >= 0) {
        return true;
      }

      var cy = a.surfaceY(a.x, a.z);
      if (ny >= cy) return false;

      var climb = a.climb || 1;
      var dirs = [[1,0],[0,1],[-1,0],[0,-1]];
      var exitCount = 0;

      for (var k = 0; k < 4; k++) {
        var tx = nx + dirs[k][0], tz = nz + dirs[k][1];
        if (tx >= 1 && tx < W - 1 && tz >= 1 && tz < D - 1) {
          var ty = a.surfaceY(tx, tz);
          if (ty >= 0 && (ty - ny) <= climb) {
            exitCount++;
          }
        }
      }

      if (exitCount === 0) {
        game.skills.recordTrapPitVisit(a, nx, nz);
        return true;
      }
      return false;
    },

    recordPeakVisit: function(a) {
      var surfY = a.surfaceY(a.x, a.z);
      if (surfY < 0) return;

      var isLocalMax = true;
      var hasLowerNeighbor = false;
      var maxNeighborY = -1;
      for (var dz = -1; dz <= 1; dz++) {
        for (var dx = -1; dx <= 1; dx++) {
          if (dx === 0 && dz === 0) continue;
          var ny = a.surfaceY(a.x + dx, a.z + dz);
          if (ny > surfY) { isLocalMax = false; break; }
          if (ny >= 0 && ny > maxNeighborY) maxNeighborY = ny;
          if (surfY > ny && ny >= 0) hasLowerNeighbor = true;
        }
        if (!isLocalMax) break;
      }
      var MIN_PROMINENCE = 3;
      var prominence = surfY - maxNeighborY;
      if (!isLocalMax || !hasLowerNeighbor || prominence < MIN_PROMINENCE) return;

      var existingNoteObj = findExistingNoteInRadius(a, 'visitas a la cima', 2) || findExistingNoteInRadius(a, 'pino de emergencia', 2);
      var existingNote = existingNoteObj ? existingNoteObj.note : '';
      var notePos = existingNoteObj ? existingNoteObj.pos : [a.x, surfY, a.z];
      var sk = a.vars.skills || {};

      var peakVisits = {};
      if (existingNote) {
        var lines = existingNote.split('\n');
        for (var i = 1; i < lines.length; i++) {
          var line = lines[i].trim();
          if (line.indexOf('Causa:') === 0 || line.indexOf('Cotas') === 0 || line.indexOf('Z-') === 0 || line.indexOf('Z=') === 0 || line.indexOf('Z+') === 0) {
            break;
          }
          var p = line.split(': ');
          if (p.length === 2) {
            var agentName = p[0].trim();
            if (agentName.indexOf('Z-') === 0 || agentName.indexOf('Z=') === 0 || agentName.indexOf('Z+') === 0 || agentName.indexOf('Causa') === 0) continue;
            var c = parseInt(p[1]);
            if (agentName && !isNaN(c)) peakVisits[agentName] = c;
          }
        }
      }

      if (sk.visitaCimaUnaSolaVez && peakVisits[a.name] && peakVisits[a.name] >= 1) {
        return;
      }

      peakVisits[a.name] = (peakVisits[a.name] || 0) + 1;

      var outLines = ['visitas a la cima'];
      for (var nameKey in peakVisits) {
        outLines.push(nameKey + ': ' + peakVisits[nameKey] + ' veces');
      }
      var causeStr = 'Causa: Promontorio local prominente (prominencia: ' + prominence + ' bloques)';
      outLines.push(causeStr);
      outLines.push(get3x3HeightGridStr(a, notePos[0], notePos[2], notePos[1]));
      var noteText = outLines.join('\n');
      a.note(noteText, notePos);
      attachNoteTrace(a, notePos, 'visitas a la cima', causeStr, 'onTick() -> recordPeakVisit() -> a.note()');
    },

    findNextStepToNearestUnvisited: function(a, excludeCols) {
      var W = mc.dim.x, D = mc.dim.z;
      var v = a.vars;
      var sk = v.skills || {};

      // MEMO DE "NO QUEDA FRONTERA ALCANZABLE". Cuando la serpiente ya ha cubierto el mapa, esta BFS
      // recorre los ~8.800 nodos enteros, no encuentra objetivo y devuelve null — y se repetia 1-2 veces
      // POR TICK, para siempre. visited solo CRECE, asi que si no hay frontera no puede reaparecer sola;
      // lo unico que puede devolverla es un salto tactico a otra region conectada (por eso el epoch) o
      // que alguien visite algo nuevo (por eso el tamano de visited). El rearme periodico es la red de
      // seguridad por si el terreno cambia bajo los pies del agente.
      var memo = v.bfsSinFrontera;
      if (memo && memo.epoca === (v.bfsEpoca || 0) && memo.visitedSize === v.visited.size
          && (a.stats.ticks - memo.tick) < 600) {
        v.bfsAhorradas = (v.bfsAhorradas || 0) + 1;
        return null;
      }
      var queue = [[a.x, a.z]];
      var qi = 0;   // puntero de cola: shift() es O(n) y con el mapa cubierto la cola llega a miles
      var visitedNodes = new Set();
      visitedNodes.add(a.x + ',' + a.z);
      var parentMap = {};
      var target = null;
      var dirs = [[1,0],[0,1],[-1,0],[0,-1]];
      var climb = a.climb || 1, drop = a.drop || 3;

      // Columnas vetadas por nota (cima ya visitada / callejon sin salida / foso trampa).
      // ANTES esto se resolvia con findExistingNoteInRadius(a, '', 1) DENTRO del bucle, por cada vecino
      // de cada nodo: 27 llamadas a getNote por vecino (~944.000 por BFS con el mapa cubierto, 116 ms de
      // reloj) y ademas miraba el entorno del AGENTE, no la celda candidata — o sea que ni siquiera
      // vetaba lo que pretendia. El indice se construye ahora una sola vez desde mc.notes (unas pocas
      // entradas) y el veto pasa a ser una consulta O(1) sobre la celda correcta.
      var colsVetadas = new Set();
      var marcaAgente = a.name + ':';
      var todasNotas = (typeof mc !== 'undefined' && mc.notes) ? mc.notes : {};
      for (var nk in todasNotas) {
        var txt = todasNotas[nk];
        if (!txt || txt.indexOf(marcaAgente) < 0) continue;
        var veta = (sk.visitaCimaUnaSolaVez && txt.indexOf('visitas a la cima') >= 0)
                || txt.indexOf('callejon sin salida') >= 0
                || txt.indexOf('foso trampa') >= 0;
        if (!veta) continue;
        var pp = nk.split(',');
        if (pp.length === 3) colsVetadas.add(pp[0] + ',' + pp[2]);
      }

      while (qi < queue.length) {
        var curr = queue[qi++];
        var cx = curr[0], cz = curr[1];
        var cy = a.surfaceY(cx, cz);
        var bodyY = cy >= 0 ? cy + 1 : -1;

        if (cy >= 0 && !v.visited.has(cx + ',' + bodyY + ',' + cz)) {
          var isFloating = (a.y <= 17 && cy > 16)
          if (!isFloating && (!excludeCols || !excludeCols.has(cx + ',' + cz))) {
            target = [cx, cz];
            break;
          }
        }

        for (var i = 0; i < 4; i++) {
          var dx = dirs[i][0], dz = dirs[i][1];
          var nx = cx + dx, nz = cz + dz;
          if (nx >= 1 && nx < W - 1 && nz >= 1 && nz < D - 1) {
            if (cx === a.x && cz === a.z && !a.canWalk(dx, dz)) continue;
            if (cx === a.x && cz === a.z && excludeCols && excludeCols.has(nx + ',' + nz)) continue;
            if (cx === a.x && cz === a.z && game.skills.isTrapPit(a, nx, nz)) continue;

            var ny = a.surfaceY(nx, nz);
            var hDiff = ny - cy;
            if (ny >= 0 && hDiff <= climb && hDiff >= -drop) {
              var key = nx + ',' + nz;
              if (colsVetadas.size && colsVetadas.has(key)) continue;
              if (!visitedNodes.has(key)) {
                visitedNodes.add(key);
                parentMap[key] = [cx, cz];
                queue.push([nx, nz]);
              }
            }
          }
        }
      }

      if (target) {
        var curr = target;
        while (curr[0] !== a.x || curr[1] !== a.z) {
          var pKey = curr[0] + ',' + curr[1];
          var parent = parentMap[pKey];
          if (!parent) break;
          if (parent[0] === a.x && parent[1] === a.z) {
            var step = [curr[0] - a.x, curr[1] - a.z];
            var backDir = [-v.dir[0], -v.dir[1]];
            if (step[0] === backDir[0] && step[1] === backDir[1]) {
              var ortho1 = [v.dir[1], -v.dir[0]], ortho2 = [-v.dir[1], v.dir[0]];
              if (isCellValidExit(a, ortho1[0], ortho1[1])) return ortho1;
              if (isCellValidExit(a, ortho2[0], ortho2[1])) return ortho2;
            }
            return step;
          }
          curr = parent;
        }
      }
      if (!target && !excludeCols) {
        v.bfsSinFrontera = { epoca: v.bfsEpoca || 0, visitedSize: v.visited.size, tick: a.stats.ticks };
      }
      return null;
    },

    saltoTactico: function(a, motivo) {
      var now = performance.now();
      if (a.vars.lastJumpAt && (now - a.vars.lastJumpAt < 3000)) return false;
      // Un barrido que NO encuentra destino cuesta lo mismo que uno que si (2 x 96x96 surfaceY + claves
      // de texto) y con el mapa cubierto es SIEMPRE el caso. Sin este freno se repetia en cada llamada:
      // el cooldown de arriba solo se armaba en el camino de exito.
      if (a.vars.lastJumpFailAt && (now - a.vars.lastJumpFailAt < 3000)) return false;

      var W = mc.dim.x, D = mc.dim.z;
      var bestDist = 1e9, bestCell = null;
      var dirs = [[1,0],[0,1],[-1,0],[0,-1]];

      for (var z = 1; z < D - 1; z++) {
        for (var x = 1; x < W - 1; x++) {
          var y = a.surfaceY(x, z);
          if (y >= 0 && !a.vars.visited.has(x + ',' + (y + 1) + ',' + z)) {
            var openCount = 0;
            for (var k = 0; k < 4; k++) {
              if (a.canWalk(dirs[k][0], dirs[k][1])) openCount++;
            }
            if (openCount >= 2) {
              var dist = Math.hypot(x - a.x, z - a.z);
              if (dist >= 5 && dist < bestDist) { bestDist = dist; bestCell = { x: x, y: y, z: z }; }
            }
          }
        }
      }
      if (!bestCell) {
        for (var z = 1; z < D - 1; z++) {
          for (var x = 1; x < W - 1; x++) {
            var y = a.surfaceY(x, z);
            if (y >= 0 && !a.vars.visited.has(x + ',' + (y + 1) + ',' + z)) {
              var openCount = 0;
              for (var k = 0; k < 4; k++) {
                if (a.canWalk(dirs[k][0], dirs[k][1])) openCount++;
              }
              if (openCount >= 2) {
                var dist = Math.hypot(x - a.x, z - a.z);
                if (dist < bestDist) { bestDist = dist; bestCell = { x: x, y: y, z: z }; }
              }
            }
          }
        }
      }

      if (bestCell) {
        logExecutionStep(a, 'TACTICAL_JUMP', 'Salto a [' + bestCell.x + ',' + (bestCell.y + 1) + ',' + bestCell.z + '] (' + (motivo || 'Escape') + ')');
        a.x = bestCell.x; a.y = bestCell.y + 1; a.z = bestCell.z;
        a.renderX = bestCell.x; a.renderY = bestCell.y + 1; a.renderZ = bestCell.z;
        a.stats.jumps = (a.stats.jumps || 0) + 1;
        a.vars.historial = [];
        a.vars.lastTicketAt = {};
        a.vars.lastCount = a.vars.visited.size;
        a.vars.lastJumpAt = now;
        a.vars.stepsWithoutNewCell = 0;

        // Modo serpiente: el teletransporte parte el cuerpo en dos, asi que se descarta y se vuelve a
        // formar detras de la cabeza en su nueva posicion.
        a.vars.cuerpo = [];
        a.vars.cuerpoSalientes = [];
        a.vars.ultimoPaso = null;
        emitAgentToast(a, '\u26A1 \u00A1' + a.name + ': Salto T\u00E1ctico a [' + bestCell.x + ',' + (bestCell.y + 1) + ',' + bestCell.z + '] (' + (motivo || 'Escape') + ')!', 'jump');
        console.log('[SALTO TÁCTICO - ' + a.name + '] Tras ' + (motivo || 'encierro') + ', saltó a [' + bestCell.x + ',' + (bestCell.y + 1) + ',' + bestCell.z + ']');
        a.vars.bfsEpoca = (a.vars.bfsEpoca || 0) + 1;   // otra region conectada: invalida el memo de frontera
        a.vars.bfsSinFrontera = null;
        return true;
      }
      a.vars.lastJumpFailAt = now;
      return false;
    },

    plantarPinoDeEmergencia: function(a) {
      var surfY = a.surfaceY(a.x, a.z);
      if (surfY < 0) return;
      var px = a.x, pz = a.z;
      var py = surfY + 1;

      a.setBlock(px, py, pz, 'tronco');
      a.setBlock(px, py + 1, pz, 'tronco');

      for (var dx = -1; dx <= 1; dx++) {
        for (var dz = -1; dz <= 1; dz++) {
          a.setBlock(px + dx, py + 2, pz + dz, 'hierba');
        }
      }

      a.setBlock(px, py + 3, pz, 'hierba');
      a.setBlock(px + 1, py + 3, pz, 'hierba');
      a.setBlock(px - 1, py + 3, pz, 'hierba');
      a.setBlock(px, py + 3, pz + 1, 'hierba');
      a.setBlock(px, py + 3, pz - 1, 'hierba');
      a.setBlock(px, py + 4, pz, 'hierba');

      var causeStr = 'Causa: Emergencia por encierro extremo.';
      var noteText = 'pino de emergencia\n' + a.name + ': Piqué un túnel de emergencia para salir y planté este pino cónico piramidal como hito de rescate.\n' + causeStr + '\n' + get3x3HeightGridStr(a, px, pz, surfY);
      var notePos = [px, py, pz];
      a.note(noteText, notePos);
      emitAgentToast(a, '\u1F332 \u00A1' + a.name + ': Plant\u00F3 un pino c\u00F3nico piramidal 3D con nota justificativa!', 'pino');
      attachNoteTrace(a, notePos, 'pino de emergencia', causeStr, 'minadoEmergencia() -> plantarPinoDeEmergencia() -> a.note()');
    },

    minadoEmergencia: function(a, dirs) {
      var W = mc.dim.x, D = mc.dim.z;
      var minedAny = false;
      var minedDir = null;

      game.skills.plantarPinoDeEmergencia(a);

      for (var m = 0; m < 4; m++) {
        var md = dirs[m];
        var mx = a.x + md[0], mz = a.z + md[1];
        if (mx >= 1 && mx < W - 1 && mz >= 1 && mz < D - 1) {
          var my = a.surfaceY(mx, mz);
          var cy = a.surfaceY(a.x, a.z);
          if (my > cy || !a.canWalk(md[0], md[1])) {
            for (var yLevel = cy + 1; yLevel <= Math.max(my, cy + 2); yLevel++) {
              var b = a.getBlock(mx, yLevel, mz);
              if (b !== 0) {
                a.setBlock(mx, yLevel, mz, 0);
                minedAny = true;
              }
            }
            if (minedAny && !minedDir) minedDir = md;
          }
        }
      }

      if (minedAny) {
        logExecutionStep(a, 'EMERGENCY_MINE', 'Picó túnel de emergencia');
        a.stats.mined = (a.stats.mined || 0) + 1;
        if (minedDir) a.vars.dir = minedDir;
        a.vars.historial = [];
        emitAgentToast(a, '\u26CF\uFE0F \u00A1' + a.name + ': Pic\u00F3 t\u00FAnel de emergencia para abrir salida!', 'minado');
        console.log('[MINADO EMERGENCIA] ' + a.name + ' picó bloques de muro en torno a ' + a.x + ',' + a.y + ',' + a.z + ' para abrir salida física.');
        return true;
      }
      return false;
    },

    rebobinadoHistorico: function(a, backDir) {
      if (a.vars.historial.length >= 2) {
        a.vars.historial.pop();
        logExecutionStep(a, 'REWIND', 'Marcha atrás por historial');
        emitAgentToast(a, '\u1F504 ' + a.name + ': Rebobinando marcha atr\u00E1s por historial...', 'rebobinado');
        a.vars.dir = backDir;
      }
    },

    asciiMap: function(a) {
      var W = mc.dim.x, D = mc.dim.z;
      var lines = ['=== MAPA 2D INDIVIDUAL: Agente ' + a.name + ' (' + a.vars.visited.size + ' celdas 3D recorridas) Run ' + a.vars.runId + ' ==='];
      for (var z = 0; z < D; z++) {
        var row = '';
        for (var x = 0; x < W; x++) {
          if (x === a.x && z === a.z) row += '@';
