        + ' Pos:[' + a.x + ',' + a.y + ',' + a.z + ']'
        + ' Dir:[' + v.dir + '] (' + cardStr + ')'
        + ' Y:[' + yMin + '-' + yMax + ']'
        + abilStr
        + ' Recientes:' + (uniqueRecent ? uniqueRecent.size : 0) + '/10'
        + ' Cobertura3D:' + v.visited.size + '/' + v.totalWalkable
        + ' Hist:[' + v.historial.slice(-5).join('->') + ']';

      var ticketStr = 'Ticket ' + v.runId + ' [' + motivo + '] ' + compacto;
