      emitAgentToast(a, '\u1F916 ' + a.name + ': Ticket #' + count + ' (' + motivo + ')', 'ticket');
      console.log('[TICKET - ' + a.name + '] ' + ticketStr + '\n' + diag3x3);

      if (count >= 5) {
        a.stop('5x_' + motivo);
        v.show3x3();
        v.asciiMap();
        v.showTickets();
