                var isDoorPattern = (bBottom !== yellowId && bMiddle === 0 && bTop !== 0);

                if (isDoorPattern || isRedConcrete) {
                  // Restricción: No construir si ya existen bloques de obsidiana pegados (radio 2)
                  var hasNearbyObsidian = false;
                  for (var checkDz = -2; checkDz <= 2; checkDz++) {
