                      for (var checkDy = -1; checkDy <= 3; checkDy++) {
                        var cx = fx + checkDx, cy = collisionY + checkDy, cz = fz + checkDz;
                        if (cx >= 0 && cx < W && cz >= 0 && cz < D && cy >= 0) {
