                    { x: fx + 2 * ortho[0], y: collisionY + 1, z: fz + 2 * ortho[1] },
                    { x: fx + 2 * ortho[0], y: collisionY + 0, z: fz + 2 * ortho[1] },
                    { x: fx - 2 * ortho[0], y: collisionY + 2, z: fz - 2 * ortho[1] },
