        }

        var ortho1 = [v.dir[1], -v.dir[0]], ortho2 = [-v.dir[1], v.dir[0]];
        var canFront = isCellValidExit(a, v.dir[0], v.dir[1]);
        var canOrtho1 = isCellValidExit(a, ortho1[0], ortho1[1]);
        var canOrtho2 = isCellValidExit(a, ortho2[0], ortho2[1]);

        var physFront = a.canWalk(v.dir[0], v.dir[1]) && !game.skills.isTrapPit(a, a.x + v.dir[0], a.z + v.dir[1]);
        var physOrtho1 = a.canWalk(ortho1[0], ortho1[1]) && !game.skills.isTrapPit(a, a.x + ortho1[0], a.z + ortho1[1]);
        var physOrtho2 = a.canWalk(ortho2[0], ortho2[1]) && !game.skills.isTrapPit(a, a.x + ortho2[0], a.z + ortho2[1]);
        var isPhysicalDeadEnd = !physFront && !physOrtho1 && !physOrtho2;

        if (v.escapeSteps > 0 && physFront) {
          // Mantener inercia de escape
        } else if (!canFront) {
          if (canOrtho1) {
            v.dir = ortho1;
            logExecutionStep(a, 'TURN_ORTHO1', 'Giro a la derecha por obstáculo frontal');
          } else if (canOrtho2) {
            v.dir = ortho2;
            logExecutionStep(a, 'TURN_ORTHO2', 'Giro a la izquierda por obstáculo frontal');
