        }

        var uniqueRecent = new Set(v.historial.slice(-8));

        var isBorderZone = (a.x <= 2 || a.x >= W - 3 || a.z <= 2 || a.z >= D - 3);
        if (isBorderZone) {
          // UMBRAL DE MERODEO EN EL BORDE. Ojo con bajarlo: la caja de 5x5 de aqui abajo contiene
          // SIEMPRE tu celda actual + las 2 que acabas de dejar atras, asi que cualquier umbral <= 3 es
          // verdadero por construccion desde el tercer paso, y el contador deja de medir estancamiento
          // para convertirse en un simple "estoy cerca del borde". Cruzar la caja en linea recta deposita
          // como mucho 5 visitas, de ahi que 8 separe "paso de largo" de "estoy dando vueltas aqui".
          var BORDER_LOITER_MIN = 8;
          var BORDER_QUIETO_MIN = 8;   // ticks seguidos sin moverse que cuentan como merodeo
          var minBorderWindow = a.stats.ticks - 50;
          var borderVisits = 0;
          for (var i = v.recentVisits.length - 1; i >= 0; i--) {
            if (v.recentVisits[i].tick < minBorderWindow) break;
            if (Math.abs(v.recentVisits[i].x - a.x) <= 2 && Math.abs(v.recentVisits[i].z - a.z) <= 2) {
              borderVisits++;
            }
          }
          if (borderVisits >= BORDER_LOITER_MIN || (v.ticksQuieto || 0) >= BORDER_QUIETO_MIN) {
            var interiorDir = null;
            if (a.x <= 2) interiorDir = [1, 0];
            else if (a.x >= W - 3) interiorDir = [-1, 0];
            else if (a.z <= 2) interiorDir = [0, 1];
            else if (a.z >= D - 3) interiorDir = [0, -1];

            if (interiorDir && isCellValidExit(a, interiorDir[0], interiorDir[1])) {
