          var cellA = recentCells[0].split(','), cellB = recentCells[1] ? recentCells[1].split(',') : cellA;
          var otherX = (+cellA[0] === a.x && +cellA[2] === a.z) ? +cellB[0] : +cellA[0];
          var otherZ = (+cellA[0] === a.x && +cellA[2] === a.z) ? +cellB[2] : +cellA[2];

          var escapeDx = a.x - otherX;
          var escapeDz = a.z - otherZ;
          escapeDx = escapeDx > 0 ? 1 : (escapeDx < 0 ? -1 : 0);
          escapeDz = escapeDz > 0 ? 1 : (escapeDz < 0 ? -1 : 0);

