              v.escapeMotivo = 'escape vectorial de oscilacion en 2 celdas';
              logExecutionStep(a, 'LOOP_ESCAPE_2CELL', 'Escape vectorial de oscilación 2 celdas');
              var movedLoop = a.walk(escapeDx, escapeDz);
              if (movedLoop) {
                v.historial = [];
                return;
              }
            }
          }
        }

