            if (!a.vars.cuerpo) a.vars.cuerpo = [];
            if (!a.vars.cuerpoSalientes) a.vars.cuerpoSalientes = [];
            return a.vars;
          };
          var esCuerpo = function(x, z) {
            var c = vars().cuerpo;
            for (var i = 0; i < c.length; i++) if (c[i].x === x && c[i].z === z) return true;
            return false;
          };
          var prohibido = function(dx, dz) {
            var p = vars().ultimoPaso;
            if (p && dx === -p[0] && dz === -p[1]) return true;      // giro de 180 grados
            return esCuerpo(a.x + dx, a.z + dz);                     // morderse la cola
          };
          a.walk = function(dx, dz) {
            if (game.skills.desnivelProhibido(a, dx, dz)) {
              a.stats.blockedBySlope = (a.stats.blockedBySlope || 0) + 1;
              return false;
            }
            var sk = a.vars.skills;
            var modo = sk && sk.modoSerpiente;
            if (modo && prohibido(dx, dz)) {
              // Valvula de escape: si NINGUNA otra direccion es viable dejamos pasar el movimiento, antes
              // que congelar al agente emitiendo tickets de estancamiento para siempre.
              var salida = false;
              for (var i = 0; i < 4; i++) {
                var d = DIRS4[i];
                if ((d[0] !== dx || d[1] !== dz) && !prohibido(d[0], d[1]) && a.canWalk(d[0], d[1])) { salida = true; break; }
              }
              if (salida) { a.stats.blockedBySelf = (a.stats.blockedBySelf || 0) + 1; return false; }
            }
            var antesX = a.x, antesZ = a.z;
            var ok = _origWalk.call(a, dx, dz);
            if (modo && ok && (a.x !== antesX || a.z !== antesZ)) {
              vars().ultimoPaso = [a.x - antesX, a.z - antesZ];
              vars().cuerpo.unshift({ x: antesX, z: antesZ });        // la celda que se abandona pasa a ser cuerpo
              while (a.vars.cuerpo.length > largoSerpiente) a.vars.cuerpoSalientes.push(a.vars.cuerpo.pop());
            }
            return ok;
          };
        }

        a.enqueueBlock = function(x, y, z, block) {
          a.vars.buildQueue = a.vars.buildQueue || [];
          a.vars.buildQueue.push({ action: 'setBlock', x: x, y: y, z: z, block: block });
          if (!a.vars.isBuildingAsync) processAgentBuildQueue(a);
        };
        a.enqueuePaint = function(x, z, block) {
          a.vars.buildQueue = a.vars.buildQueue || [];
          a.vars.buildQueue.push({ action: 'paint', x: x, z: z, block: block });
          if (!a.vars.isBuildingAsync) processAgentBuildQueue(a);
        };

        logExecutionStep(a, 'START', 'Agente iniciado en [' + a.x + ',' + a.y + ',' + a.z + ']');

        if (typeof game.addMaterial === 'function') {
          if (config.block) await game.addMaterial(config.block);
          if (config.paintBlock) await game.addMaterial(config.paintBlock);
          if (config.buildBlock) await game.addMaterial(config.buildBlock);
          if (config.triggerFloor) await game.addMaterial(config.triggerFloor);
          await game.addMaterial('obsidiana');
          await game.addMaterial('obsidian');
          await game.addMaterial('red_concrete');
          await game.addMaterial('tronco');
          await game.addMaterial('hierba');
        }

        if (typeof mcMat2id !== 'undefined') mcMat2id = {};
        a._mat = {};

        a.vars.recentVisits.push({ x: a.x, z: a.z, y: a.y, tick: a.stats.ticks });
        a.vars.totalWalkable = game.skills.getCurrentWalkable3D(a);

        if (config.paintBlock) a.vars.paintId = a.matId(config.paintBlock);
        if (config.triggerFloor) a.vars.triggerId = a.matId(config.triggerFloor);
        if (config.buildBlock) a.vars.buildId = a.matId(config.buildBlock);

        a.stats.built = 0;
        a.stats.mined = 0;
        a.stats.jumps = 0;

        var d = new Date();
        a.vars.runId = d.getHours() + ':' + String(d.getMinutes()).padStart(2,'0') + ':' + String(d.getSeconds()).padStart(2,'0');

        a.vars.show3x3 = function() { var diag = game.skills.local3x3Diagnostic(a); console.log(diag); return diag; };
        a.vars.asciiMap = function() { return game.skills.asciiMap(a); };
        a.vars.showTickets = function() { return game.skills.showTickets(a); };
        a.vars.showToastHistory = function() {
          console.log('=== HISTORIAL DE TOASTS (' + a.name + ' - Total ' + a.vars.toastHistory.length + ') ===');
          for (var i = 0; i < a.vars.toastHistory.length; i++) console.log(a.vars.toastHistory[i]);
          return a.vars.toastHistory;
        };
        a.vars.showHeatmap = function(windowTicks) {
          var W = mc.dim.x, D = mc.dim.z;
          var grid = calculateAgentDensity(a, windowTicks);
          var modeTitle = windowTicks ? ('Últimos ' + windowTicks + ' Ticks / ~' + Math.round(windowTicks*0.2) + 's') : 'Acumulado Total de Pasadas Físicas';
          var lines = ['=== REJILLA 2D DEL MAPA DE CALOR DE OSCILACIÓN: ' + a.name + ' (' + modeTitle + ') ==='];
          var header = '  [Z\\X] ';
          for (var x = 0; x < W; x++) header += (x % 10);
          lines.push(header);
          for (var z = 0; z < D; z++) {
            var row = (' Z=' + String(z).padStart(2, '0') + ': ').substring(0, 8);
            for (var x = 0; x < W; x++) {
              if (x === a.x && z === a.z) {
                row += '@';
              } else {
                var count = grid[x + ',' + z] || 0;
                row += getHeatSymbol(count);
              }
            }
            lines.push(row);
          }
          lines.push('LEYENDA: . = Tránsito Fluido (1-2) | ░ = Templado (3-5) | ▒ = Oscilación (6-9) | █ = 🔥 ATASCO CRÍTICO (10+) | @ = Agente (' + a.x + ',' + a.z + ')');
          var out = lines.join('\n');
          console.log(out);
          return out;
        };
        a.vars.tacticalJump = function(motivo) { return game.skills.saltoTactico(a, motivo); };
        a.vars.traceNote = function(x, y, z) {
          var key = (x !== undefined && y !== undefined && z !== undefined) ? (x + ',' + y + ',' + z) : (a.x + ',' + a.y + ',' + a.z);
          return game.traceNote(key);
        };

        if (typeof config.onStart === 'function') {
          var userStart = config.onStart(a);
          if (userStart && typeof userStart.then === 'function') await userStart;
        }

        console.log('[F12] ' + a.name + ' (BFS Frontier Optimal) iniciado. Total caminable inicial: ' + a.vars.totalWalkable + ' celdas 3D. Run ' + a.vars.runId);
        console.log('  .vars.show3x3()         --> Diagnóstico 3x3 Local');
        console.log('  .vars.asciiMap()        --> Mapa 2D');
        console.log('  .vars.showTickets()     --> Historial de tickets');
        console.log('  .vars.showToastHistory()--> Historial de toasts emitidos');
        console.log('  .vars.showHeatmap()     --> Rejilla 2D del Mapa de Calor de Oscilación');
        console.log('  .vars.traceNote(x,y,z)  --> TRAZA COMPLETA DE EJECUCIÓN DE NOTA DESDE EL INICIO');
        console.log('  game.agents()           --> Tabla general');
        console.log('  game.stuck()            --> DIAGNÓSTICO DIRECTO DE AGENTES EN ATASCO ACTIVO');
        console.log('  game.toastLog()         --> Registro global de toasts');
        console.log('  game.heatmap()          --> Rejilla 2D del Mapa de Calor Global');
        console.log('  game.traceNote(x,y,z)   --> Inspeccionar traza histórica completa de una nota');
      },

      onTick(a) {
        // El cuerpo del tick estandar tiene ~12 `return` tempranos, y tres de ellos salen JUSTO DESPUES
        // de un a.walk() con exito (escape de oscilacion, escape por frecuencia y desmontar del pino).
        // Llamar a config.onTick desde dentro del cuerpo hacia que el hook del snippet se perdiera en
        // esos caminos: el agente se movia y su onTick no se enteraba, sin poder recuperarse nunca.
        // El try/finally garantiza que config.onTick se llama SIEMPRE, una vez por tick, aunque el tick
        // estandar salga antes de tiempo o lance.
        // El perfilador envuelve el tick ENTERO (no solo el tick estandar) para que el desglose por
        // fases sume lo mismo que el coste real: si 'tick' es mucho mayor que la suma de las fases
        // medidas, el tiempo se va en codigo aun sin instrumentar, y eso tambien es informacion.
        game.perfData._tickFases = {};
        var _t0 = performance.now();
        try {
          try { ejecutarTickEstandar(a); }
          finally { if (typeof config.onTick === 'function') medir('onTick', function(){ config.onTick(a); }); }
        } finally {
          var _dt = performance.now() - _t0;
          var pd = game.perfData;
          pd.ticks++;
          var ft = pd.fases['tick'] || (pd.fases['tick'] = { llamadas: 0, ms: 0, maxMs: 0 });
          ft.llamadas++; ft.ms += _dt; if (_dt > ft.maxMs) ft.maxMs = _dt;
          if (_dt > 30) {   // solo los ticks que de verdad se notan como tiron
            var desg = [], tf = pd._tickFases, dom = '-', domMs = 0;
            for (var fk in tf) {
              desg.push(fk + ' ' + tf[fk].toFixed(1) + 'ms');
              if (tf[fk] > domMs) { domMs = tf[fk]; dom = fk; }
            }
            if (domMs < _dt * 0.5) dom = 'sin instrumentar (' + (_dt - domMs).toFixed(0) + 'ms fuera de fases)';
            pd.peores.push({ hora: new Date().toLocaleTimeString('es-ES'), tick: a.stats.ticks,
                             agente: a.id, ms: _dt, dominante: dom, desglose: desg.join(' · ') });
            if (pd.peores.length > 60) pd.peores.shift();
          }
          pd._tickFases = null;
        }
      }
    });
  };
